hunks.after:
if v_t.pay_basis_kind='RETAINED_PAID_MATCH' then
  v_paid_basis:=private.weekly_source_paid_match_retained_transition_assert_v1(v_t.id);
end if;
select s.movement_id into v_movement from private.bpay_next_source_current_snapshots s
  where s.snapshot_line_id=v_t.previous_snapshot_line_id and s.scope_id=v_scope and s.work_event_id=v_t.work_event_id;
if v_paid_basis is not null and (v_paid_basis->>'snapshot_line_id' is distinct from v_t.previous_snapshot_line_id::text
  or v_paid_basis->>'movement_id' is distinct from v_movement::text
  or v_paid_basis->>'row_resolution_id' is distinct from v_origin_resolution::text
  or v_paid_basis->>'lineage_id' is distinct from v_lineage::text
  or v_paid_basis->>'economic_snapshot_id' is distinct from v_economic::text) then
  raise exception 'BPAY_NEXT_SOURCE_RETAINED_PAID_BASIS_UNBOUND' using errcode='55000';end if;
